+
+      function drawAxes(svg, cfg) {
+        const { x0, y0, w, h } = cfg;
+        svg.appendChild(el("line", { x1: x0, y1: y0 + h, x2: x0 + w, y2: y0 + h, stroke: cssVar("--axis"), "stroke-width": 1 }));
+        svg.appendChild(el("line", { x1: x0, y1: y0, x2: x0, y2: y0 + h, stroke: cssVar("--axis"), "stroke-width": 1 }));
+      }
+
+      function drawGrid(svg, cfg, xticks, yticks) {
+        const { x0, y0, w, h } = cfg;
+        for (const t of xticks) {
+          const x = x0 + (t.pos * w);
+          svg.appendChild(el("line", { x1: x, y1: y0, x2: x, y2: y0 + h, stroke: cssVar("--grid"), "stroke-width": 1 }));
+        }
+        for (const t of yticks) {
+          const y = y0 + h - (t.pos * h);
+          svg.appendChild(el("line", { x1: x0, y1: y, x2: x0 + w, y2: y, stroke: cssVar("--grid"), "stroke-width": 1 }));
+        }
+      }
+
+      function drawTickLabels(svg, cfg, xticks, yticks, xfmt, yfmt) {
+        const { x0, y0, w, h } = cfg;
+        for (const t of xticks) {
+          const x = x0 + (t.pos * w);
+          const label = el("text", { x, y: y0 + h + 18, fill: cssVar("--muted"), "font-size": 11, "text-anchor": "middle" });
+          label.textContent = xfmt(t.value);
+          svg.appendChild(label);
+        }
+        for (const t of yticks) {
+          const y = y0 + h - (t.pos * h);
+          const label = el("text", { x: x0 - 8, y: y + 4, fill: cssVar("--muted"), "font-size": 11, "text-anchor": "end" });
+          label.textContent = yfmt(t.value);
+          svg.appendChild(label);
+        }
+      }
