+      function linePath(points) {
+        return points.map((p, i) => `${i === 0 ? "M" : "L"}${p[0].toFixed(2)},${p[1].toFixed(2)}`).join(" ");
+      }
+
+      function renderBarChart(svgId, labels, series, opts) {
+        const svg = document.getElementById(svgId);
+        if (!svg) return;
+        svg.innerHTML = "";
+
+        const width = 720;
+        const height = parseFloat(svg.getAttribute("viewBox").split(" ")[3]);
+        const pad = { l: 50, r: 18, t: 18, b: 34 };
+        const x0 = pad.l;
+        const y0 = pad.t;
+        const w = width - pad.l - pad.r;
+        const h = height - pad.t - pad.b;
+
+        const values = series.flatMap((s) => s.values);
+        const maxV = Math.max(...values, 1);
+
+        const xticks = labels.map((lab, i) => ({ value: lab, pos: labels.length === 1 ? 0.5 : i / (labels.length - 1) }));
+        const yticks = [0, 0.25, 0.5, 0.75, 1].map((p) => ({ value: Math.round(maxV * p), pos: p }));
+        drawGrid(svg, { x0, y0, w, h }, xticks, yticks);
+        drawAxes(svg, { x0, y0, w, h });
+        drawTickLabels(svg, { x0, y0, w, h }, xticks, yticks, (v) => v, (v) => fmt(v));
+
+        const groupCount = labels.length;
+        const seriesCount = series.length;
+        const groupW = w / groupCount;
+        const barW = Math.min(32, (groupW * 0.75) / seriesCount);
+        const gap = Math.max(2, (groupW * 0.75 - barW * seriesCount) / (seriesCount + 1));
+
+        labels.forEach((lab, i) => {
+          const baseX = x0 + i * groupW + (groupW * 0.125);
+          series.forEach((s, j) => {
+            const v = s.values[i];
+            const barH = (v / maxV) * h;
+            const x = baseX + gap + j * (barW + gap);
+            const y = y0 + h - barH;
+            svg.appendChild(
+              el("rect", {
+                x,
+                y,
+                width: barW,
+                height: barH,
+                fill: s.color,
+                rx: 6,
+                opacity: 0.92,
+              })
+            );
+          });
+        });
+
+        if (opts && opts.legend) {
+          const lx = x0 + w - 10;
+          let ly = y0 + 8;
+          series.forEach((s) => {
+            svg.appendChild(el("rect", { x: lx - 140, y: ly - 9, width: 10, height: 10, fill: s.color, rx: 2 }));
+            const t = el("text", { x: lx - 124, y: ly, fill: cssVar("--muted"), "font-size": 11, "text-anchor": "start" });
+            t.textContent = s.name;
+            svg.appendChild(t);
+            ly += 16;
+          });
+        }
+      }
