+        const xticks = xValues.map((x) => ({ value: x, pos: (x - xmin) / (xmax - xmin || 1) }));
+        const yticks = cfg.yticks.map((y) => ({ value: y, pos: (y - ymin) / (ymax - ymin || 1) }));
